{"code": "import openpyxl

# Verify all sheets exist and spot-check data integrity
dst = openpyxl.load_workbook('summary.xlsx', data_only=True)
src = openpyxl.load_workbook('./materials/FinancialStatementFY26Q4.xlsx', data_only=True)

print("Destination sheets:", dst.sheetnames)
print("Source sheets:", src.sheetnames)
print("Match:", dst.sheetnames == src.sheetnames + ['Summary'])

# Spot check a few cells in each original sheet
for name in src.sheetnames:
    s = src[name]
    d = dst[name]
    print(f"\n{name}: src max_row={s.max_row}, dst max_row={d.max_row}, max_col={s.max_column}")
    # Check A1
    print(f"  A1: src={s['A1'].value}, dst={d['A1'].value}")
    # Check last populated cell
    src_last = None
    for row in s.iter_rows(min_row=1, max_row=s.max_row, max_col=s.max_column):
        for c in row:
            if c.value is not None:
                src_last = (c.coordinate, c.value)
    dst_last = None
    for row in d.iter_rows(min_row=1, max_row=d.max_row, max_col=d.max_column):
        for c in row:
            if c.value is not None:
                dst_last = (c.coordinate, c.value)
    print(f"  Last cell: src={src_last}, dst={dst_last}")"}
